static void sen_get_mode_basic_hi5011q(CTL_SENDRV_GET_MODE_BASIC_PARAM *mode_basic)
{
	UINT32 mode = mode_basic->mode;
	
	if (1 == (mode >> 12)) {
		mode = mode & 0xF;
		if (mode >= SEN_MAX_MODE) {
			mode = 0;
		}
		memcpy(mode_basic, &mode_basic_param[mode], sizeof(CTL_SENDRV_GET_MODE_BASIC_PARAM));
		mode_basic->valid_size.w =  mode_basic->act_size[1].w;
		mode_basic->valid_size.h =  mode_basic->act_size[1].h;
	} else {
		mode = mode & 0xF;
		if (mode >= SEN_MAX_MODE) {
			mode = 0;
		}
		memcpy(mode_basic, &mode_basic_param[mode], sizeof(CTL_SENDRV_GET_MODE_BASIC_PARAM));
	}
}

