static void sen_get_speed_hi5011q(CTL_SEN_ID id, CTL_SENDRV_GET_SPEED_PARAM *data)
{
	UINT32 mode = data->mode;

	mode = mode & 0xF;

	if (mode >= SEN_MAX_MODE) {
		mode = 0;
	}
	memcpy(data, &speed_param[mode], sizeof(CTL_SENDRV_GET_SPEED_PARAM));

	if (sen_power[id].mclk == CTL_SEN_CLK_SEL_SIEMCLK) {
		data->mclk_src = CTL_SEN_SIEMCLK_SRC_MCLK;
	} else if (sen_power[id].mclk == CTL_SEN_CLK_SEL_SIEMCLK2) {
		data->mclk_src = CTL_SEN_SIEMCLK_SRC_MCLK2;
	} else if (sen_power[id].mclk == CTL_SEN_CLK_SEL_SIEMCLK3) {
		data->mclk_src = CTL_SEN_SIEMCLK_SRC_MCLK3;
	} else if (sen_power[id].mclk == CTL_SEN_CLK_SEL_SIEMCLK4) {
		data->mclk_src = CTL_SEN_SIEMCLK_SRC_MCLK4;
	} else if (sen_power[id].mclk == CTL_SEN_IGNORE) {
		data->mclk_src = CTL_SEN_SIEMCLK_SRC_IGNORE;
	} else {
		DBG_ERR("mclk source is fail \r\n");
	}
}

static void sen_get_mode_mipi_hi5011q(CTL_SENDRV_GET_MODE_MIPI_PARAM *data)
{
	UINT32 mode = data->mode;

	mode = mode & 0xF;
	
	if (mode >= SEN_MAX_MODE) {
		mode = 0;
	}
	memcpy(data, &mipi_param[mode], sizeof(CTL_SENDRV_GET_MODE_MIPI_PARAM));
}

static void sen_get_modesel2_hi5011q(CTL_SENDRV_GET_MODESEL2_PARAM *data)
{
	if (data->info[0].if_type != CTL_SEN_IF_TYPE_MIPI) {
		DBG_ERR("if_type %d N.S. \r\n", data->info[0].if_type);
		return;
	}

	if (data->info[0].data_fmt != CTL_SEN_DATA_FMT_RGB) {
		DBG_ERR("data_fmt %d N.S. \r\n", data->info[0].data_fmt);
		return;
	}

	if (data->frame_num == 1) {
		if ((data->info[0].size.w <= 4096) && (data->info[0].size.h <= 3072)) {
			if (data->info[0].frame_rate <= 3010) {
				data->mode = CTL_SEN_MODE_2;
				return;
			}				
		}		
	} else if (data->frame_num == 2) {
		if (data->info[0].vendor_param[CTL_SEN_EXT_MODESEL_VENDOR_TYPE_PD] == CTL_SEN_EXT_MODESEL_VENDOR_PARAM_PD_VIRTUAL_CHANNEL) {
			if ((data->info[0].size.w <= 4096) && (data->info[0].size.h <= 3072)) {
				if ((data->info[1].size.w <= 4096) && (data->info[1].size.h <= 768)) {					
					if (data->info[0].frame_rate <= 3010) {
						data->mode = CTL_SEN_MODE_1;
						return;
					}
				}
			}
		}
	}

	DBG_ERR("index 0 => (frame_rate%d,size%d*%d,if_type%d,data_fmt%d,frame_num%d) \r\n"
			, data->info[0].frame_rate, data->info[0].size.w, data->info[0].size.h, data->info[0].if_type, data->info[0].data_fmt, data->frame_num);
	DBG_ERR("index 1 => fail (frame_rate%d,size%d*%d,if_type%d,data_fmt%d,frame_num%d) \r\n"
			, data->info[1].frame_rate, data->info[1].size.w, data->info[1].size.h, data->info[1].if_type, data->info[1].data_fmt, data->frame_num);	
	data->mode = CTL_SEN_MODE_1;
}

static void sen_get_modesel_hi5011q(CTL_SENDRV_GET_MODESEL_PARAM *data)
{

}

static UINT32 sen_calc_rowtime_step_hi5011q(CTL_SEN_ID id, CTL_SEN_MODE mode)
{
	UINT32 div_step = 1;

	if (mode >= SEN_MAX_MODE) {
		mode = cur_sen_mode[id];
	}

	if ((mode_basic_param[mode].mode_type == CTL_SEN_MODE_LINEAR) || (mode_basic_param[mode].mode_type == CTL_SEN_MODE_PDAF)) {
		div_step = 1;
	}

	return div_step;
}

static UINT32 sen_calc_rowtime_hi5011q(CTL_SEN_ID id, CTL_SEN_MODE mode)
{
	UINT32 row_time = 0;

	if (mode >= SEN_MAX_MODE) {
		mode = cur_sen_mode[id];
	}

	//Precision * 10
	row_time = 10 * (mode_basic_param[mode].signal_info.hd_period) / ((speed_param[mode].pclk) / 1000000);

	return row_time;
}

static void sen_get_rowtime_hi5011q(CTL_SEN_ID id, CTL_SENDRV_GET_MODE_ROWTIME_PARAM *data)
{
	UINT32 mode = data->mode;

	mode = mode & 0xF;

	if (mode >= SEN_MAX_MODE) {
		mode = cur_sen_mode[id];
	}
	
	data->row_time_step = sen_calc_rowtime_step_hi5011q(id, mode);	
	data->row_time = sen_calc_rowtime_hi5011q(id, mode) * (data->row_time_step);
}

static void sen_get_mipi_mfr_outsel_hi5011q(CTL_SEN_ID id, CTL_SENDRV_MIPI_MFR_OUTSEL_PARAM *data)
{
	UINT32 mode = data->mode;

	mode = mode & 0xF;

	if (mode >= SEN_MAX_MODE) {
		mode = cur_sen_mode[id];
	}

	if (mode == CTL_SEN_MODE_1) {
		data->outsel = CTL_SEN_MIPI_MFR_OUTSEL_VC;
	}
}

